{
  uint32_t abi_version;
  uint32_t cid_pid;
  uint32_t core_count;
  uint32_t page_size;
  uint32_t pool_size;
  uint32_t pool_free;
  uint32_t max_buffers;
  uint32_t max_timeout_ms;
};

