{
  uint32_t size;
  uint32_t flags;
  uint32_t handle;
  uint32_t physical;
  uint32_t vip_address;
  uint32_t allocated;
  uint64_t cpu_address;
};

struct a733_npu_free_s
{
  uint32_t handle;
  uint32_t reserved;
};

struct a733_npu_cache_s
{
  uint32_t handle;
  uint32_t offset;
  uint32_t size;
  uint32_t reserved;
};

