{
  uint32_t command_handle;
  uint32_t command_offset;
  uint32_t command_size;
  uint32_t timeout_ms;
  uint32_t flags;
  uint32_t task_id;
  int32_t status;
  uint32_t irq_value;
  uint32_t idle;
