#define A733_NPUIOC_CANCEL         _DIOC(0xe7)
#define A733_NPUIOC_RESET          _DIOC(0xe8)
#define A733_NPUIOC_SELFTEST       _DIOC(0xe9)
#define A733_NPUIOC_MODEL_PROBE    _DIOC(0xea)
#define A733_NPUIOC_STAGE_FILE     _DIOC(0xeb)

